// SkillCatalogName returns the Dark Pawns display name for skill/spell
// number num, or "" if the slot is unused/reserved/out of range (C spells[]).
func SkillCatalogName(num int) string {
	if num < 0 || num >= len(dpSkillCatalogNames) {
		return ""
	}
	name := dpSkillCatalogNames[num]
	if name == "!UNUSED!" || name == "!RESERVED!" {
		return ""
	}
	return name
}
